import{_ as e,C as a,o as n,c as l,j as r,a as o,E as s,a3 as i}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Графики и рисование","description":"","frontmatter":{},"headers":[],"relativePath":"ru/customize/chart-colors.md","filePath":"ru/customize/chart-colors.md"}'),h={name:"ru/customize/chart-colors.md"};function c(b,t,g,k,p,u){const d=a("Screenshot");return n(),l("div",null,[t[0]||(t[0]=r("h1",{id:"графики-и-рисование",tabindex:"-1"},[o("Графики и рисование "),r("a",{class:"header-anchor",href:"#графики-и-рисование","aria-label":'Permalink to "Графики и рисование"'},"​")],-1)),t[1]||(t[1]=r("p",null,[o("Эти настройки находятся во вкладке "),r("strong",null,"Home"),o(" главного окна, в секции "),r("strong",null,"Charts"),o(". Они глобальные: их использует каждый график в каждом инструменте — Knives, Alerts, Analyzer, Monitor, Ticks, Terminal.")],-1)),s(d,{src:"charts-colors",alt:"Секция настроек Charts во вкладке Home",caption:"Home → Charts"}),t[2]||(t[2]=i('<h2 id="палитра" tabindex="-1">Палитра <a class="header-anchor" href="#палитра" aria-label="Permalink to &quot;Палитра&quot;">​</a></h2><p>Каждый цвет в Sentaro — и здесь, и в цветах метрик Monitor, и во внешнем виде Terminal — открывает одну и ту же палитру:</p><ul><li>Квадрат <strong>насыщенности / яркости</strong>, под ним ползунок <strong>оттенка</strong>.</li><li>Ползунок <strong>непрозрачности</strong>. Любой цвет в приложении можно сделать полупрозрачным.</li><li>Поле <strong>hex</strong>, которое принимает 3, 4, 6 или 8 символов (<code>#f00</code>, <code>#f00a</code>, <code>#ff0000</code>, <code>#ff0000aa</code>), и процент текущей непрозрачности рядом.</li></ul><p>Образец, открывающий палитру, нарисован поверх шахматной клетки, так что полупрозрачный цвет видно и без открытия.</p><div class="info custom-block"><p class="custom-block-title">Где хранится непрозрачность</p><p>В большинстве мест — цвета свечей, цвет рисунков и все цвета метрик Monitor — <strong>непрозрачность является частью значения hex</strong>. При полной непрозрачности это обычный 6-символьный hex; как только опускаете ниже 100%, он становится 8-символьным <code>#rrggbbaa</code>.</p><p>Исключение — сгруппированные цвета внешнего вида Terminal: там цвет и его непрозрачность хранятся двумя отдельными значениями, поэтому в той панели рядом с каждой записью показан процент.</p></div><h2 id="цвета-свечеи" tabindex="-1">Цвета свечей <a class="header-anchor" href="#цвета-свечеи" aria-label="Permalink to &quot;Цвета свечей&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Настройка</th><th>Что делает</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Bullish candle</strong></td><td>Цвет свечей, закрывшихся вверх</td><td><code>#9D9D9D</code>, полностью непрозрачный</td></tr><tr><td><strong>Bearish candle</strong></td><td>Цвет свечей, закрывшихся вниз</td><td><code>#4A4A4A</code>, полностью непрозрачный</td></tr></tbody></table><p>Оба открывают палитру. Изменение сразу применяется ко всем графикам в приложении, так что выбранная здесь схема свечей сопровождает вас от миниатюры в Knives до полноэкранной панели в Analyzer.</p><p>Цвета по умолчанию намеренно нейтрально-серые, а не зелёно-красные: задумка в том, чтобы цвет в интерфейсе означал «что-то пересекло порог», а не «цена пошла вверх». Если вам привычнее классические зелёные и красные свечи — задайте их здесь.</p><h2 id="гистограмма-объема" tabindex="-1">Гистограмма объёма <a class="header-anchor" href="#гистограмма-объема" aria-label="Permalink to &quot;Гистограмма объёма&quot;">​</a></h2><p>Каждый свечной график может показывать <strong>гистограмму объёма</strong>: по одному столбику на свечу внизу графика, окрашенному по направлению свечи. Наведите на столбик, чтобы увидеть значение. Объём показывается в единицах, которые сообщает биржа (монеты или контракты), а не в долларах.</p><table tabindex="0"><thead><tr><th>Настройка</th><th>Что делает</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Volume up color</strong></td><td>Цвет столбика для свечей, закрывшихся вверх</td><td><code>#5eaf82</code> с непрозрачностью 50%</td></tr><tr><td><strong>Volume down color</strong></td><td>Цвет столбика для свечей, закрывшихся вниз</td><td><code>#d47c7c</code> с непрозрачностью 50%</td></tr><tr><td><strong>Volume histogram key</strong></td><td>Включает/выключает гистограмму</td><td><kbd>V</kbd></td></tr></tbody></table><p>По умолчанию она <strong>включена</strong> везде. Есть два вида переключателей:</p><ul><li><strong>Для инструмента</strong> — кнопка <strong>Vol Ind</strong> в заголовке Knives, Monitor, Ticks и Terminal и <strong>Vol</strong> в Analyzer. Включает или выключает гистограмму на всех графиках этого окна.</li><li><strong>Полноэкранный</strong> — один общий переключатель для всех полноэкранных графиков во всех инструментах.</li></ul><p>Клавиша <kbd>V</kbd> переключает тот, что действует сейчас: обычно переключатель окна, а когда открыт полноэкранный график — полноэкранный.</p><h2 id="сетка-графика" tabindex="-1">Сетка графика <a class="header-anchor" href="#сетка-графика" aria-label="Permalink to &quot;Сетка графика&quot;">​</a></h2><p><strong>Chart grid</strong> включает или выключает фоновые линии сетки — горизонтальные и вертикальные — на всех графиках. По умолчанию включено.</p><h2 id="цвет-рисунков" tabindex="-1">Цвет рисунков <a class="header-anchor" href="#цвет-рисунков" aria-label="Permalink to &quot;Цвет рисунков&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Настройка</th><th>Что делает</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Drawing color</strong></td><td>Цвет всех пяти инструментов рисования</td><td>Наследует акцентный цвет</td></tr></tbody></table><p>Один цвет действует на все инструменты рисования. Если вы его никогда не меняли, он следует за акцентным цветом, выбранным во вкладке Home; как только вы зададите его явно, он перестаёт следить за акцентом и остаётся таким, как вы поставили.</p><h2 id="инструменты-рисования" tabindex="-1">Инструменты рисования <a class="header-anchor" href="#инструменты-рисования" aria-label="Permalink to &quot;Инструменты рисования&quot;">​</a></h2><p>Графики в <a href="/manual/ru/tools/analyzer.html">Analyzer</a> и в полноэкранных видах поддерживают пять инструментов рисования. Каждый привязан к одной клавише, и каждую привязку можно изменить здесь.</p><table tabindex="0"><thead><tr><th>Инструмент</th><th>Что рисует</th><th>Клавиша по умолчанию</th></tr></thead><tbody><tr><td><strong>Horizontal ray key</strong></td><td>Горизонтальный луч на выбранной цене</td><td><kbd>H</kbd></td></tr><tr><td><strong>Trend line key</strong></td><td>Трендовую линию по двум точкам</td><td><kbd>T</kbd></td></tr><tr><td><strong>Rectangle key</strong></td><td>Прямоугольник / область</td><td><kbd>B</kbd></td></tr><tr><td><strong>Pencil key</strong></td><td>Свободное рисование</td><td><kbd>P</kbd></td></tr><tr><td><strong>Dissolving pencil key</strong></td><td>Свободное рисование, которое исчезает само</td><td><kbd>F</kbd></td></tr><tr><td><strong>Majors overlay key</strong></td><td>Показывает/скрывает <a href="/manual/ru/customize/majors.html">слой мажоров</a> на графике под курсором</td><td><kbd>M</kbd></td></tr><tr><td><strong>Volume histogram key</strong></td><td>Показывает/скрывает <a href="#гистограмма-объема">гистограмму объёма</a></td><td><kbd>V</kbd></td></tr></tbody></table><p>Чтобы переназначить, нажмите кнопку клавиши рядом — она переключится на <code>Press a key…</code> — и нажмите нужную клавишу. <kbd>Esc</kbd> отменяет без изменений.</p><p>Несколько правил, которые применяет захват клавиш:</p><ul><li>Для пяти инструментов рисования принимаются только буквы и цифры.</li><li>Комбинации с модификаторами отклоняются — нажатие <kbd>Ctrl</kbd>+<kbd>H</kbd> ничего не даст, привязка должна быть голой клавишей.</li><li>Привязки должны быть уникальными. Если выбрать клавишу, уже назначенную другому инструменту, захват отменяется и ничего не меняется.</li></ul><p>Привязки хранятся как физические позиции клавиш, а не символы, так что они продолжают работать после смены раскладки или набора на другом языке.</p><p>Рисунки хранятся для каждого символа <em>и</em> для каждой биржи, так что переключение графика с Bybit на Binance для того же тикера покажет другой набор рисунков.</p><h2 id="магнит" tabindex="-1">Магнит <a class="header-anchor" href="#магнит" aria-label="Permalink to &quot;Магнит&quot;">​</a></h2><p>Магнит привязывает точку, которую вы ставите, к ближайшему максимуму или минимуму свечи, чтобы лучи и трендовые линии ложились точно на тень, а не рядом с ней.</p><table tabindex="0"><thead><tr><th>Настройка</th><th>Что делает</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Magnet</strong> режим</td><td><code>Hold</code> или <code>Toggle</code></td><td><code>Hold</code></td></tr><tr><td><strong>Magnet</strong> клавиша</td><td>Клавиша, которая его включает</td><td><kbd>Ctrl</kbd> (левый)</td></tr></tbody></table><p>Два режима:</p><ul><li><strong>Hold</strong> — магнит активен, только пока клавиша нажата. Мгновенный.</li><li><strong>Toggle</strong> — нажатие включает магнит, повторное нажатие выключает. Состояние сохраняется между перезапусками.</li></ul><p>В отличие от инструментов рисования, клавишей магнита <strong>может</strong> быть голый модификатор — <kbd>Ctrl</kbd>, <kbd>Shift</kbd>, <kbd>Alt</kbd> или <kbd>Meta</kbd> — а также буква или цифра. По умолчанию это левый <kbd>Ctrl</kbd>. То же правило об отсутствии дубликатов действует и в отношении пяти клавиш рисования.</p><h2 id="чего-здесь-нет" tabindex="-1">Чего здесь нет <a class="header-anchor" href="#чего-здесь-нет" aria-label="Permalink to &quot;Чего здесь нет&quot;">​</a></h2><p>Цвета, которые показывают пересечение порога метрикой, настраиваются в самих инструментах, а не глобально — потому что сами пороги тоже принадлежат инструментам:</p><ul><li>Цвета уровней NATR и % Change в Monitor, контуры и заливки → <a href="/manual/ru/tools/monitor.html#metric-colors">Monitor → Metric colors</a></li><li>Цвета лестницы, полос глубины и позиций в Terminal → <a href="/manual/ru/tools/terminal.html#внешнии-вид">Terminal → Внешний вид</a></li></ul>',37))])}const y=e(h,[["render",c]]);export{f as __pageData,y as default};
